{
  "application": "ppt-generation",
  "case_id": "case-ossinsight",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 8,
    "audience": "developer advocates, open-source community managers, and engineering leaders tracking AI tooling trends",
    "tone": "data-forward, analytical, technically grounded"
  },
  "brief": {
    "title": "GitHub Trending Repos Snapshot: The Rise of AI Coding Agents and Claude Code Skills",
    "one_liner": "An analysis of the top 20 trending GitHub repositories in the past 24 hours reveals overwhelming dominance of AI coding agent tools, Claude Code skill extensions, and developer productivity utilities.",
    "goal": "The audience should understand which categories of AI-related open-source projects are surging in popularity, identify the key repos and patterns driving the trend, and assess strategic implications for developer tooling investment."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "GitHub Trending Repos Snapshot: The Rise of AI Coding Agents & Claude Code Skills",
      "objective": "Cover slide with deck title, subtitle referencing OSSInsight's 10.6B+ GitHub events dataset, and date context. Clean, visually striking layout."
    },
    {
      "id": "platform-overview",
      "title": "OSSInsight Tracks 10.6 Billion GitHub Events in Real Time",
      "objective": "Introduce OSSInsight as the data source, highlighting its scale (10.6B events, stars/PRs/issues/commits/reviews). Use a few key stats as callout numbers to establish credibility."
    },
    {
      "id": "top-5-trending-repos",
      "title": "hermes-agent Leads with 1,347 Stars — Top 5 Repos by Total Score",
      "objective": "Present a ranked table or horizontal bar chart of the top 5 trending repos (hermes-agent, graphify, awesome-design-md, caveman, claude-code-best-practice) with stars, forks, pushes, and PRs. Highlight the dominant lead of #1."
    },
    {
      "id": "language-distribution",
      "title": "Python and TypeScript Dominate Trending Repos' Language Mix",
      "objective": "Show a pie or donut chart of programming languages across the top 20 repos (Python: 7, TypeScript: 4, HTML: 2, Rust: 2, Swift: 2, Shell: 1, Java: 1, Unspecified: 1). Emphasize Python's outsized 35% share and note that one repo has no specified language."
    },
    {
      "id": "category-breakdown",
      "title": "14 of 20 Trending Repos Are AI Coding Agent or Claude Code Projects",
      "objective": "Categorize the top 20 repos into thematic buckets (AI coding agents/skills, Claude Code tools, developer utilities, other). Use a stacked bar or treemap to show that ~70% relate directly to AI coding assistance."
    },
    {
      "id": "claude-code-ecosystem",
      "title": "Claude Code Spawns an Ecosystem: Skills, Guides, Switches, and Best Practices",
      "objective": "Highlight the Claude Code ecosystem. The core Claude Code Ecosystem Tools category includes 5 repos (claude-code-best-practice, claude-howto, cc-switch, caveman, learn-claude-code), while the Key Findings note at least 7 repos broadly serve as Claude Code skills, guides, best-practice collections, or multi-tool switchers when including cross-listed repos like oh-my-codex and agent-skills from the AI Coding Agents & Skills category. Use a network or list visual showing the breadth of the emerging ecosystem, clearly distinguishing the 5 core Claude Code tools from the broader set."
    },
    {
      "id": "community-engagement",
      "title": "hermes-agent Draws 78 PRs and 42 Pushes — Community Activity Varies Widely",
      "objective": "Compare community engagement metrics (PRs and pushes) across the top 20 repos using a scatter plot or grouped bar chart. Contrast high-engagement repos (hermes-agent, multica) with zero-PR repos to show varying maturity levels."
    },
    {
      "id": "key-takeaways",
      "title": "Key Takeaways: AI Coding Agents Are GitHub's Hottest Category",
      "objective": "Summarize 4-5 bullet-point findings: AI agent dominance, Claude Code ecosystem explosion, Python leadership, community engagement concentration, and implications for developer tooling strategy. Clean text layout with icons or checkmarks."
    }
  ]
}

