201	    pointer-events: none;
202	    transition: opacity 0.3s ease;
203	    z-index: 10001;
204	}
205	.edit-toggle.show,
206	.edit-toggle.active {
207	    opacity: 1;
208	    pointer-events: auto;
209	}
210	```
211	
212	JS (three interaction methods):
213	```javascript
214	// 1. Click handler on the toggle button
215	document.getElementById('editToggle').addEventListener('click', () => {
216	    editor.toggleEditMode();
217	});
218	
219	// 2. Hotzone hover with 400ms grace period
220	const hotzone = document.querySelector('.edit-hotzone');
221	const editToggle = document.getElementById('editToggle');
222	let hideTimeout = null;
223	
224	hotzone.addEventListener('mouseenter', () => {
225	    clearTimeout(hideTimeout);
226	    editToggle.classList.add('show');
227	});
228	hotzone.addEventListener('mouseleave', () => {
229	    hideTimeout = setTimeout(() => {
230	        if (!editor.isActive) editToggle.classList.remove('show');
231	    }, 400);
232	});
233	editToggle.addEventListener('mouseenter', () => {
234	    clearTimeout(hideTimeout);
235	});
236	editToggle.addEventListener('mouseleave', () => {
