        executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined,
        args: ['--no-sandbox', '--disable-setuid-sandbox']
    }});
    const page = await browser.newPage();
    await page.setViewportSize({{ width: {width}, height: {height} }});
    await page.goto('{url}', {{ waitUntil: 'networkidle' }});

    // Wait for fonts to load
    await page.waitForTimeout(2000);

    // Count slides
    const slideCount = await page.$$eval('.slide', els => els.length);
    console.log('Found ' + slideCount + ' slides');

    // Capture each slide by scrolling directly to it
    for (let i = 0; i < slideCount; i++) {{
        // Scroll to the slide
        await page.evaluate((idx) => {{
            const slides = document.querySelectorAll('.slide');
            if (slides[idx]) {{
                slides[idx].scrollIntoView({{ behavior: 'instant' }});
                // Force visibility for animations
                slides[idx].classList.add('visible');
            }}
        }}, i);

        // Wait for rendering
        await page.waitForTimeout(800);

        const idx = String(i + 1).padStart(3, '0');
        const path = `{out_dir}/slide_${{idx}}.png`;
        await page.screenshot({{ path }});
        console.log('Captured slide ' + (i + 1));
    }}

    console.log(JSON.stringify({{ captured: slideCount }}));
    await browser.close();
}})();
"""


def _start_http_server(directory: Path, port: int = 0):
    handler = http.server.SimpleHTTPRequestHandler
    server = http.server.HTTPServer(("127.0.0.1", port), lambda *a, **kw: handler(*a, directory=str(directory), **kw))
    actual_port = server.server_address[1]
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    return server, actual_port


def main():
    html_path = Path("/app/output/presentation.html").resolve()
    output_path = Path("/app/output/final_deck.pptx").resolve()

    with tempfile.TemporaryDirectory(prefix="slides_") as tmp:
        tmp_dir = Path(tmp)
        serve_dir = html_path.resolve().parent
        server, port = _start_http_server(serve_dir)
        url = f"http://127.0.0.1:{port}/{html_path.resolve().name}"

        script = _make_screenshot_script(url, str(tmp_dir), 1920, 1080)
        script_file = tmp_dir / "_capture.cjs"
        script_file.write_text(script)

        env = os.environ.copy()
        env.setdefault("NODE_PATH", "/usr/local/lib/node_modules:/app/node_modules")
        env.setdefault("PLAYWRIGHT_BROWSERS_PATH", "/ms-playwright")
        env.setdefault("PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD", "1")

        try:
            result = subprocess.run(
                ["node", str(script_file)],
                capture_output=True,
                text=True,
                timeout=300,
                env=env,
            )
            if result.returncode != 0:
                print(f"Playwright stderr:\n{result.stderr}", file=sys.stderr)
                raise RuntimeError(f"Screenshot script failed (exit {result.returncode})")
            print(f"Playwright stdout:\n{result.stdout}")
        finally:
            server.shutdown()

        pngs = sorted(tmp_dir.glob("slide_*.png"))
        print(f"Found {len(pngs)} slide images")

        if not pngs:
            raise RuntimeError("No slide screenshots produced")

        # Assemble PPTX
        prs = Presentation()
        prs.slide_width = Emu(12192000)
        prs.slide_height = Emu(6858000)
        blank_layout = prs.slide_layouts[6]

        for img_path in pngs:
            slide = prs.slides.add_slide(blank_layout)
            slide.shapes.add_picture(
                str(img_path),
                left=Emu(0),
                top=Emu(0),
                width=prs.slide_width,
                height=prs.slide_height,
            )

        prs.save(str(output_path))
        print(f"Done → {output_path}")


if __name__ == "__main__":
    main()
